    {"구절": "요 3:17", "연결점": "세상을 심판하러 온 것이 아니라 구원하러 오심", "구분": "신약"},
    {"구절": "마 12:41", "연결점": "예수님이 요나와 니느웨를 직접 언급하심", "구분": "신약"},
    {"구절": "벧후 3:9", "연결점": "아무도 멸망하지 않고 다 회개에 이르기를 원하시는 하나님", "구분": "신약"},
    {"구절": "행 17:30", "연결점": "모든 곳의 모든 사람에게 회개를 명하시는 하나님", "구분": "신약"}
