  "본문": "사공이 두려워하여 각각 자기의 신을 부르고 또 배를 가볍게 하려고 그 가운데 물건을 바다에 던지니라 그러나 요나는 배 밑층에 내려가서 누워 깊이 잠이 든지라",
  "절요약": "폭풍 속 기도하는 이방인과 잠든 선지자 - 영적 역설",
