    {"항목": "이방인의 도덕적 직관", "내용": "이방 선원들이 요나의 행동을 즉각적으로 비판 - '어찌하여 이렇게 하였느냐'. 하나님 없이도 도덕적 잘못을 알아채는 일반 은총", "목회적활용": "일반 은총으로 도덕적 직관이 있는 이방인들 - 그들도 하나님의 형상을 지닌 존재"}
