    {"구분": "이방인들의 두려움", "내용": "요나의 고백으로 이방인들이 여호와를 두려워함", "그리스도연결": "예수님의 십자가로 이방인들이 하나님께 나아오게 됨 (엡 2:13)"},
    {"구분": "이방인의 책망", "내용": "이방 선원들이 요나의 불순종을 질책함", "그리스도연결": "심판 날에 니느웨 사람들이 일어나 정죄할 것이라는 예수님의 말씀 (마 12:41)"}
