    {"교리": "기도의 도달", "설명": "물고기 뱃속에서 드린 기도가 성전에 미침 - 공간적 제약이 기도를 막지 않는다", "관련구절": "왕상 8:30, 단 6:10, 시 65:2, 마 6:6"},
    {"교리": "기억과 믿음", "설명": "하나님을 기억하는 것이 믿음의 실천 - 안식일, 성찬, 세례 모두 기억의 행위", "관련구절": "신 8:18, 시 77:11, 눅 22:19, 신 16:3"}
