  "표5_매튜헨리": [
    {"영어원문": "Jonah arose and went to Nineveh — this time there was no delay, no running away. The obedience was prompt and complete.", "한국어번역": "요나가 일어나 니느웨로 갔다 - 이번에는 지체도 도망도 없었다. 순종은 신속하고 완전했다.", "핵심통찰": "진정한 회개는 즉각적 순종으로 이어진다"},
    {"영어원문": "According to the word of the LORD — the best obedience is that which is most exactly conformable to the divine will.", "한국어번역": "여호와의 말씀대로 - 최선의 순종은 하나님의 뜻에 가장 정확하게 일치하는 것이다.", "핵심통찰": "순종의 척도는 하나님의 말씀이다"},
    {"영어원문": "Nineveh was an exceeding great city — the greatness of the city did not discourage Jonah now, as perhaps it had before.", "한국어번역": "니느웨는 극히 큰 성읍이었다 - 성읍의 크기가 이번에는 요나를 낙담시키지 않았다. 아마도 이전에는 그랬을지라도.", "핵심통찰": "고난 후 회복된 믿음은 두려움을 이긴다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "말씀대로 - 완전한 순종의 모습", "예화_적용": ""},
    {"대지": "서론", "내용": "요나가 드디어 일어났다. 이번에는 다시스가 아닌 니느웨로. '여호와의 말씀대로.' 이 짧은 표현이 그의 변화를 보여준다. 물고기 뱃속의 고난이 그를 말씀에 순종하는 자로 만들었다.", "예화_적용": "수 11:15 - 여호수아가 여호와께서 모세에게 명령하신 대로 다 행하였더라"},
    {"대지": "1대지: 일어나서 (결단의 행동)", "내용": "생각만이 아닌 몸을 일으킴 - 순종은 결단이고 행동이다. 요나는 생각을 바꾸었고 그 생각이 발을 움직였다.", "예화_적용": "아브라함이 일어나 갔다(창 12:4) - 믿음은 행동으로 증명된다"},
    {"대지": "2대지: 말씀대로 (완전한 일치)", "내용": "'키드바르 야훼' - 말씀대로. 내 방식이 아닌 하나님의 방식대로 가는 것이 진정한 순종이다.", "예화_적용": "다윗이 하나님의 마음에 합한 자라고 불린 이유 - 하나님의 뜻대로 행하는 자(행 13:22)"},
    {"대지": "결론", "내용": "당신은 하나님의 말씀대로 일어나고 있는가? 큰 성읍처럼 보이는 두려운 사명 앞에서도 말씀대로 일어나는 것이 신앙이다.", "예화_적용": ""}
  ],
