    {"원어": "וְנִינְוֵה נֶהְפָּכֶת (베니느웨 네흐파케트)", "의미_문법": "니느웨가 뒤집어지리라, 동사 니팔 분사형 - 완전한 변화/멸망", "설교포인트": "뒤집어진다는 표현은 소돔처럼 완전한 심판을 의미한다"},
    {"원어": "וַיִּקְרָא (바이크라)", "의미_문법": "외쳤다, 동사 칼 미완료 바브연속형 - 공개적 선포", "설교포인트": "복음 선포는 공개적이고 담대한 외침이어야 한다"}
