    {"구분": "하나님의 진노를 돌이키심", "내용": "회개로 인해 심판이 거두어질 가능성", "그리스도연결": "그리스도의 십자가 - 하나님의 진노가 그리스도에게 쏟아져 신자의 죄가 용서됨(롬 3:25)"},
    {"구분": "멸망하지 않게 하심", "내용": "심판을 피하는 구원의 소망", "그리스도연결": "요 3:16 - 멸망하지 않고 영생을 얻는 그리스도 안의 구원"}
