  "표5_매튜헨리": [
    {"영어원문": "Who can tell if God will turn and repent — they did not presume on God's mercy, but neither did they despair of it.", "한국어번역": "누가 하나님이 돌이키실지 알겠느냐 - 그들은 하나님의 긍휼을 당연히 여기지 않았지만 그것에 대해 절망하지도 않았다.", "핵심통찰": "하나님의 긍휼을 당연히 여기지도, 절망하지도 않는 믿음의 균형"},
    {"영어원문": "Who knows? — this is not a despairing question but a hopeful one. It leaves room for the mercy of God.", "한국어번역": "누가 알겠느냐 - 이것은 절망의 질문이 아니라 소망의 질문이다. 그것은 하나님의 긍휼을 위한 여지를 남긴다.", "핵심통찰": "불확실한 믿음 속에도 소망이 있다"},
    {"영어원문": "The very uncertainty of mercy is a motive to seek it — even Jonah's threatening had a saving intent behind it.", "한국어번역": "긍휼의 불확실성 자체가 그것을 구하는 동기가 된다 - 요나의 경고에는 구원의 의도가 숨어 있었다.", "핵심통찰": "심판의 경고 뒤에는 구원의 초청이 있다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "누가 알겠느냐 - 불확실 속의 믿음", "예화_적용": ""},
    {"대지": "서론", "내용": "'혹시'와 '누가 알겠느냐.' 니느웨 왕은 결과를 보장받지 못했다. 그래도 회개했다. 이것이 진정한 믿음이다. 결과가 확실할 때만 행동하는 것은 믿음이 아니다.", "예화_적용": "욥 13:15 - 그가 나를 죽이실지라도 나는 그를 의뢰하리니"},
    {"대지": "1대지: 혹시 돌이키실까 (조건부 소망)", "내용": "하나님의 심판에는 회개의 조건이 내포된다. 혹시라는 표현은 하나님의 주권을 인정하면서도 그분의 긍휼을 기대하는 겸손한 믿음이다.", "예화_적용": "렘 18:8 - 만일 내가 말한 그 나라가 그 악에서 돌이키면 내가 재앙을 돌이키겠고"},
    {"대지": "2대지: 누가 알겠느냐 (하나님의 주권 인정)", "내용": "결과는 하나님의 주권에 달려있다. 우리는 요구할 수 없고 구할 수 있을 뿐이다. 그러나 하나님의 성품(긍휼, 은혜, 인내)을 신뢰하여 기대한다.", "예화_적용": "삼하 12:22 - 다윗이 아이를 위해 금식 기도"},
    {"대지": "결론", "내용": "결과가 불확실해도 하나님의 긍휼을 향해 나아가라. '누가 알겠느냐'는 절망이 아닌 소망의 표현이다. 하나님은 돌이키시는 분이시다.", "예화_적용": ""}
  ],
