    {"항목": "구약 이스라엘의 민족주의", "내용": "당시 이스라엘은 하나님의 사랑과 구원을 자민족에게 국한시키는 경향이 있었다. 요나는 그 전형이다. 요나서는 이러한 편협함에 대한 도전이다", "목회적활용": "복음은 내 그룹, 내 민족을 넘어 모든 사람에게 향한다"}
