    {"구절": "요 1:14", "연결점": "은혜와 진리가 충만하더라 - 그리스도 안에 나타난 하나님의 성품", "구분": "신약"},
    {"구절": "엡 5:1", "연결점": "그러므로 사랑을 받는 자녀 같이 너희는 하나님을 본받는 자가 되고", "구분": "신약"},
    {"구절": "눅 12:47", "연결점": "주인의 뜻을 알고도 준비하지 아니한 종 - 앎의 책임", "구분": "신약"}
