  "표5_매튜헨리": [
    {"영어원문": "God prepared a gourd to shelter Jonah — he was more kind to Jonah than Jonah deserved, and than Jonah had been to Nineveh.", "한국어번역": "하나님이 요나를 위해 박넝쿨을 준비하셨다 - 하나님은 요나가 받을 자격이 있는 것보다, 그리고 요나가 니느웨에게 베푼 것보다 더 친절하셨다.", "핵심통찰": "하나님의 은혜는 우리의 자격을 초월한다"},
    {"영어원문": "Jonah was exceeding glad of the gourd — he who was sullen about the salvation of Nineveh was overjoyed at a plant.", "한국어번역": "요나가 박넝쿨 때문에 매우 기뻐했다 - 니느웨의 구원에 대해 시무룩했던 그가 식물 때문에 크게 기뻐했다.", "핵심통찰": "영적 가치 전도 - 더 큰 것에는 슬퍼하고 작은 것에 기뻐함"},
    {"영어원문": "God intended this gourd for a further purpose — to teach Jonah a lesson about compassion for Nineveh.", "한국어번역": "하나님은 이 박넝쿨을 더 깊은 목적을 위해 의도하셨다 - 요나에게 니느웨에 대한 긍휼에 관한 교훈을 가르치기 위해.", "핵심통찰": "하나님의 선물에는 교훈이 담겨있다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "박넝쿨의 은혜 - 하나님의 세심한 교훈의 준비", "예화_적용": ""},
    {"대지": "서론", "내용": "하나님이 박넝쿨을 준비하셨다. 분노하는 요나를 위해. 그 그늘 아래서 요나는 크게 기뻐했다. 그런데 이 기쁨이 반전의 단초가 된다. 하나님은 이 박넝쿨을 통해 요나에게 가장 중요한 교훈을 가르치실 것이다.", "예화_적용": "마 6:26-28 - 공중의 새와 들의 꽃을 보라 - 자연을 통해 가르치시는 예수님"},
    {"대지": "1대지: 하나님이 준비하심 (섭리의 세심함)", "내용": "박넝쿨 하나도 하나님이 준비하신다. 하나님의 섭리는 거대한 역사뿐 아니라 지친 선지자에게 필요한 그늘 하나까지 세심하게 관리하신다.", "예화_적용": "창 22:8 - 여호와 이레, 하나님이 준비하신다"},
    {"대지": "2대지: 식물에 크게 기뻐함 (뒤집어진 가치)", "내용": "니느웨 구원에는 크게 싫어하고 박넝쿨에는 크게 기뻐했다. 이 대조가 요나의 가치 전도를 보여준다. 나는 무엇에 기뻐하는가?", "예화_적용": "마 12:12 - 사람이 양보다 얼마나 더 귀하냐"},
    {"대지": "결론", "내용": "하나님의 선물에는 항상 교훈이 담겨있다. 박넝쿨의 기쁨이 끝날 때 더 깊은 진리가 기다리고 있다. 하나님의 선물에 감사하되 그 뒤의 교훈도 받아야 한다.", "예화_적용": ""}
  ],
