    {"상황": "작은 불편함에 과도하게 반응하는 성도", "성경원리": "요나는 박넝쿨 하나에 크게 기뻐하고 그것이 없어지자 죽기를 원했다 - 과도한 의존의 문제", "실제적용": "상황에 따라 흔들리지 않는 내적 안정을 하나님 안에서 찾도록 돕는다"}
