    {"교리": "반복적 교훈의 은혜", "설명": "하나님은 동일한 교훈을 포기하지 않고 반복하신다 - 인내하시는 하나님의 교육", "관련구절": "왕상 19:9-15, 요 21:15-17, 히 12:5-11"}
