    {"구분": "두 번째 죽음 소원", "내용": "반복되는 절망", "그리스도연결": "지쳐 절망하는 자를 강하게 하시는 예수님(마 11:28, 사 40:31)"},
    {"구분": "혼미함과 회복", "내용": "육체적 극한 상태", "그리스도연결": "죽으시고 부활하신 그리스도 - 극한 죽음에서 생명으로(요 11:25)"}
