    {"원어": "הֵיטֵב חָרוֹת עַד-מָוֶת (히테브 하롯 아드-마베트)", "의미_문법": "죽기까지 옳이 화났다, 강조 표현 - 완고한 자기 의의 표현", "설교포인트": "죽기까지 자기 의를 고집하는 요나 - 자기 의는 가장 깊은 죄 중 하나다"},
    {"원어": "וַיֹּאמֶר (바요메르)", "의미_문법": "그가 말하였다, 동사 칼 미완료 바브연속형 - 직접 대답", "설교포인트": "하나님의 질문에 직접 대답한 요나 - 그 대답의 내용이 문제다"}
