    {"상황": "반복적인 상담에도 변화가 없는 성도", "성경원리": "요나도 반복된 교훈에 처음에는 변하지 않았다 - 변화에는 시간이 걸린다", "실제적용": "인내하며 계속 동행하고 성령의 역사를 위해 기도한다"},
    {"상황": "하나님보다 자신의 감정을 더 신뢰하는 성도", "성경원리": "자기 감정이 옳다고 확신하는 요나 - 감정은 진실의 기준이 아니다", "실제적용": "감정은 정보이지 진실이 아님을 가르치고 하나님의 말씀을 기준으로 삼도록 돕는다"}
