    {"영어원문": "Six score thousand persons that cannot discern between their right hand and their left — these innocents plead for mercy.", "한국어번역": "오른손과 왼손을 분별하지 못하는 십이만여 명 - 이 무고한 자들이 긍휼을 간구한다.", "핵심통찰": "가장 연약하고 무지한 자들도 하나님의 긍휼의 대상이다"},
    {"영어원문": "Also much cattle — God cares for animals too; how much more for human souls made in his image.", "한국어번역": "또한 많은 가축 - 하나님은 짐승도 돌보신다. 하물며 그분의 형상으로 만들어진 인간의 영혼은 얼마나 더 돌보시겠는가.", "핵심통찰": "짐승도 돌보시는 하나님이 인간은 얼마나 더 아끼시겠는가"}
